# Сборка документа «Проблема предоплаты и финансирования проектов» (ГОСТ 7.32-2017, список источников по ГОСТ Р 7.0.100-2018).
from docx.shared import Cm
from gostdoc import Doc, build, AL
import docxchart
import natives as nv

ORG = "Проект StepPay"
TITLE = "Проблема предоплаты и финансирования проектов"
KIND = ""
AUTHOR = ""
ACCESS = "(дата обращения: 22.10.2026)"


class Note(Doc):
    fig_no = 0

    def figure(self, path, caption, width_cm=15.5):
        self.fig_no += 1
        para = self.d.add_paragraph()
        para.paragraph_format.alignment = AL.CENTER
        para.paragraph_format.keep_with_next = True
        para.paragraph_format.space_before = Cm(0.2)
        para.add_run().add_picture(path, width=Cm(width_cm))
        self.p(f"Рисунок {self.fig_no} - {caption}", size=14, indent=False, align=AL.CENTER, after=6, line=1.15)

    def chart(self, gf, caption, width_cm=15.5, height_cm=None):
        """Диаграмма Word (редактируемая, с данными во встроенной книге Excel)."""
        self.fig_no += 1
        height_cm = height_cm or gf.height.cm
        para = self.d.add_paragraph()
        para.paragraph_format.alignment = AL.CENTER
        para.paragraph_format.keep_with_next = True
        para.paragraph_format.space_before = Cm(0.2)
        docxchart.insert(para, gf, width_cm, height_cm)
        self.p(f"Рисунок {self.fig_no} - {caption}", size=14, indent=False, align=AL.CENTER, after=6, line=1.15)

    def risk_matrix(self, risks, caption):
        """Матрица рисков таблицей Word: строки - влияние 5..1, столбцы - вероятность 1..5, цвет ячейки по уровню риска."""
        from docx.oxml import OxmlElement
        from docx.oxml.ns import qn
        from docx.enum.table import WD_TABLE_ALIGNMENT, WD_CELL_VERTICAL_ALIGNMENT
        from docx.shared import Pt
        self.fig_no += 1
        t = self.d.add_table(rows=7, cols=7)
        t.style = "Table Grid"
        t.alignment = WD_TABLE_ALIGNMENT.CENTER
        w = [1.6, 0.9] + [2.5] * 5

        def put(cell, text, bold=False, fill=None, size=11, color=None):
            cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
            para = cell.paragraphs[0]
            para.paragraph_format.alignment = AL.CENTER
            para.paragraph_format.line_spacing = 1.0
            para.paragraph_format.space_after = Pt(0)
            para.paragraph_format.first_line_indent = Cm(0)
            r = para.add_run(text); r.font.size = Pt(size); r.font.bold = bold; r.font.name = "Times New Roman"
            if color:
                from docx.shared import RGBColor
                r.font.color.rgb = RGBColor.from_string(color)
            if fill:
                tcpr = cell._tc.get_or_add_tcPr()
                shd = OxmlElement("w:shd"); shd.set(qn("w:val"), "clear"); shd.set(qn("w:color"), "auto"); shd.set(qn("w:fill"), fill)
                tcpr.append(shd)

        for row in t.rows:
            row.height = Cm(1.25)
            for i, c in enumerate(row.cells):
                c.width = Cm(w[i])
        t.rows[5].height = Cm(0.8); t.rows[6].height = Cm(0.8)
        left = t.cell(0, 0).merge(t.cell(4, 0))
        put(left, "Влияние", bold=True)
        for k, imp in enumerate(range(5, 0, -1)):
            put(t.cell(k, 1), str(imp), bold=True)
            for prob in range(1, 6):
                s = prob * imp
                fill = "F4C7C3" if s >= 12 else ("FCE8B2" if s >= 6 else "D6EBDD")
                codes = ", ".join(c for c, p, i in risks if p == prob and i == imp)
                put(t.cell(k, prob + 1), codes, bold=True, fill=fill)
        for prob in range(1, 6):
            put(t.cell(5, prob + 1), str(prob), bold=True)
        t.cell(5, 0).merge(t.cell(6, 1))
        put(t.cell(6, 2).merge(t.cell(6, 6)), "Вероятность", bold=True)
        para = self.d.add_paragraph()
        para.paragraph_format.space_after = Pt(0)
        self.p(f"Рисунок {self.fig_no} - {caption}", size=14, indent=False, align=AL.CENTER, after=6, line=1.15)
        self.p("Цвет ячейки: зеленый - низкий уровень риска, желтый - средний, красный - высокий (произведение вероятности и влияния не менее 12).", size=12, indent=False, line=1.15, after=6)

    def src(self, n, text):
        self.p(f"{n}. {text}", indent=True, line=1.5, align=AL.LEFT)


def make(pages):
    D = Note()
    D.total = pages.get("__total__", "[N]")
    D.approval_and_title(ORG, TITLE, KIND, "", "Автор проекта", "2026", "", AUTHOR)
    entries = [
        (1, "ВВЕДЕНИЕ"),
        (1, "1 СУТЬ ПРОБЛЕМЫ"),
        (1, "2 АВАНС НЕ ГАРАНТИРУЕТ РЕЗУЛЬТАТ"), (2, "2.1 Частные заказы и строительство"), (2, "2.2 Субсидии и целевые средства"),
        (1, "3 ВЫПОЛНЕННАЯ РАБОТА НЕ ГАРАНТИРУЕТ ОПЛАТУ"),
        (1, "4 ПРОЕКТ ЕСТЬ, ФИНАНСИРОВАНИЯ НА РЕАЛИЗАЦИЮ НЕТ"), (2, "4.1 Гранты"), (2, "4.2 Инвестиции в проекты"),
        (1, "5 ПРИЧИНЫ"),
        (1, "6 ДЕЙСТВУЮЩИЕ МЕХАНИЗМЫ ЗАЩИТЫ И ИХ ОГРАНИЧЕНИЯ"),
        (1, "7 НАПРАВЛЕНИЕ РЕШЕНИЯ"),
        (1, "ЗАКЛЮЧЕНИЕ"),
        (1, "СПИСОК ИСПОЛЬЗОВАННЫХ ИСТОЧНИКОВ"),
    ]
    D.toc(entries, pages)

    def unnumbered(title):
        D.headings.append((1, title))
        D.center(title, bold=True, after=8)

    unnumbered("ВВЕДЕНИЕ")
    D.p("Документ описывает проблему, на решение которой направлен проект StepPay: при оплате работ, услуг, проектов и грантов ни один из привычных способов расчета не защищает обе стороны. Аванс не гарантирует заказчику результат, выполненная работа не гарантирует исполнителю оплату, а проект, у которого есть автор и план, не получает финансирования на реализацию, потому что тот, кто дает деньги, не может проверить их расходование.")
    D.p("Цель документа: показать три проявления проблемы на открытых данных 2024-2026 годов и определить требования к механизму оплаты, который снимает риск для заказчика и исполнителя одновременно. Перечень источников приведен в конце документа, обращение ко всем электронным ресурсам выполнено 22.10.2026.")

    D.h1("1", "Суть проблемы")
    D.p("При любой оплате работы стороны решают, кто рискует первым. Если заказчик платит вперед, деньги оказываются у исполнителя до получения результата: работа может быть не начата, сорвана, выполнена частично или с нарушением сроков, а исполнитель может исчезнуть. Если исполнитель работает без аванса, он вкладывает время и материалы до получения денег: заказчик может не заплатить, задержать оплату или занизить ее под предлогом недостатков. Компромиссный аванс в 30-50 % суммы делит риск между сторонами, но не устраняет его (рисунок 1).")
    D.figure("charts/fig7_dilemma.png", "Дилемма предоплаты: кто несет риск при каждом способе оплаты")
    D.p("Обе стороны проблемы подтверждаются данными. Ее признают на государственном уровне и в бизнес-сообществе: для частного домостроения введены счета эскроу [7; 8], а Российский союз промышленников и предпринимателей, наоборот, предлагает закрепить предоплату по государственным контрактам на уровне 75 % их стоимости, чтобы защитить исполнителей от неплатежей [3]. Каждая из мер защищает одну сторону за счет другой.")
    D.p("Та же дилемма возникает при финансировании проектов. Грантодатель, спонсор или инвестор передает деньги до получения результата и не может контролировать их расходование по этапам. Поэтому он сокращает число поддержанных проектов и выбирает тех, кому уже доверяет, а большинство проектов остается без финансирования на реализацию.")

    D.h1("2", "Аванс не гарантирует результат")
    D.h2("2.1", "Частные заказы и строительство")
    D.p("Наиболее заметно риск аванса проявляется в частном домостроении. По данным Банка России, около 5 тыс. льготных заемщиков, строивших дом с подрядчиком, готового жилья не получили, так как подрядчик обанкротился или исчез [5]. Число пострадавших от недобросовестных подрядчиков в ИЖС в Государственной Думе оценивают более чем в 20 тыс. человек, единого реестра пострадавших нет (рисунок 2) [4; 6].")
    D.chart(nv.izhs(), "Последствия авансирования подрядчиков в индивидуальном жилищном строительстве")
    D.p("В ремонте и бытовых услугах сводной статистики нет, но о масштабе споров говорят данные Роспотребнадзора: в 2024 году территориальные органы ведомства дали около 16,5 тыс. заключений по судебным делам в защиту прав потребителей, решения в пользу граждан приняты в 97 % случаев [9]. Это означает, что защита возможна, но наступает после потери денег и требует суда. По данным опроса клиентов сферы услуг, 22 % не доверяют исполнителям, а для 40 % надежность исполнителя является главным критерием выбора [10].")
    D.h2("2.2", "Субсидии и целевые средства")
    D.p("При финансировании проектов из бюджета аванс является нормой: средства выдаются до выполнения работ, а их использование проверяется отчетами после расходования. По заключению Счетной палаты на отчет об исполнении федерального бюджета за 2025 год, из 580,2 млрд руб. выявленных нарушений 354,7 млрд руб., или 61 %, связаны с определением объема и условий предоставления субсидий юридическим лицам (рисунок 3) [11].")
    D.chart(nv.subsidies(), "Нарушения при исполнении федерального бюджета за 2025 год, млрд руб.")

    D.h1("3", "Выполненная работа не гарантирует оплату")
    D.p("Обратная сторона проблемы касается исполнителей. По опросам РСПП, неплатежи контрагентов стали главным ограничением для бизнеса в 2025 году: о них заявили 27 % и 26 % компаний в первом и втором кварталах и 39 % и 42 % в третьем и четвертом кварталах, тогда как в 2024 году показатель находился в диапазоне 22-36 % (рисунок 4) [1; 2]. Просроченная дебиторская задолженность организаций на январь 2026 года достигла почти 8,2 трлн руб., ее доля в общей дебиторской задолженности составила 6,4 % [13].")
    D.chart(nv.nonpay(), "Доля компаний, назвавших неплатежи контрагентов главным ограничением для бизнеса, 2025 год")
    D.p("Даже в государственных закупках, где сроки оплаты установлены законом, с начала 2025 года возбуждено 1 173 административных дела о неплатежах, на 20 % больше, чем за весь 2024 год, а авансы по контрактам на практике сокращаются с 50-70 % до 30 % [3].")
    D.p("Для частных исполнителей риск выше, чем для компаний: у них нет юридической службы и запаса оборотных средств. Число самозанятых к августу 2026 года достигло 17,3 млн человек (рисунок 5) [14]. Каждый из них при работе с новым заказчиком решает вопрос предоплаты самостоятельно, а взыскание небольшой суммы через суд обходится дороже самого долга.")
    D.chart(nv.selfemployed(), "Число самозанятых (плательщиков налога на профессиональный доход), млн человек")

    D.h1("4", "Проект есть, финансирования на реализацию нет")
    D.p("Третье проявление проблемы касается авторов проектов: социальных, творческих, технологических. У проекта есть автор, план и смета, но нет денег на реализацию. Тот, кто может финансировать проект, рискует так же, как заказчик при авансе: деньги передаются до результата, а проверить их расходование можно только по отчетам после окончания работ.")
    D.h2("4.1", "Гранты")
    D.p("В 2025 году на конкурс Фонда президентских грантов поступило около 11 тыс. заявок, поддержано 1 640 проектов, то есть около 15 % (рисунок 6) [12]. Остальные проекты, в том числе прошедшие экспертизу, финансирования не получили. При отборе грантодатель оценивает не только качество проекта, но и опыт заявителя и его прошлую отчетность, поэтому новым командам получить средства сложнее.")
    D.chart(nv.grants(), "Конкурс Фонда президентских грантов в 2025 году: заявки и поддержанные проекты")
    D.h2("4.2", "Инвестиции в проекты")
    D.p("Частное финансирование новых проектов сокращается. По данным исследования Dsight, объем венчурных инвестиций в российские стартапы в 2025 году составил 159 млн долл. против 177 млн долл. в 2024 году, число сделок снизилось со 176 до 102, то есть на 42 % (рисунок 7). Сильнее всего сократилось финансирование на посевной стадии, когда у проекта есть идея и команда, но нет выручки: на 67 %, до 9 млн долл. [19]. В первом квартале 2026 года объем венчурных инвестиций снизился еще на 75 % [20].")
    D.chart(nv.venture(), "Венчурные инвестиции в российские стартапы в 2024 и 2025 годах")
    D.p("На инвестиционных платформах малый и средний бизнес в первом полугодии 2026 года привлек через выпуск акций 2,1 млрд руб., на 45 % меньше, чем годом ранее, число таких эмитентов сократилось на 9 % [21]. Инвесторы предпочитают безрисковые вклады: при высокой ключевой ставке и отсутствии контроля за расходованием средств финансирование проекта на ранней стадии для них слишком рискованно.")

    D.h1("5", "Причины")
    D.p("Анализ позволяет выделить пять причин проблемы:")
    D.p("а) деньги передаются одной стороне до того, как другая выполнила свои обязательства: при авансе до получения результата, при постоплате до получения денег;")
    D.p("б) условия договора (этапы, суммы, критерии приемки) часто не фиксируются письменно, поэтому при споре нельзя установить, что именно было согласовано и выполнено;")
    D.p("в) нет нейтрального места для денег на время выполнения работы: деньги находятся либо у заказчика, либо у исполнителя;")
    D.p("г) защита через суд наступает после потери денег и требует времени и затрат, несоразмерных сумме небольшой сделки;")
    D.p("д) тот, кто финансирует проект, не может выдавать деньги по мере выполнения этапов и останавливать финансирование при срыве, поэтому отказывает новым проектам или требует опыта и отчетности, которых у них нет.")

    D.h1("6", "Действующие механизмы защиты и их ограничения")
    D.p("Существующие механизмы закрывают проблему частично. Их сравнение приведено в таблице 1.")
    D.table("Сравнение механизмов оплаты работ", ["Механизм", "Кто несет риск", "Ограничения"], [
        ["Полная предоплата", "Заказчик", "Деньги у исполнителя до начала работ, возврат только через претензию или суд"],
        ["Оплата после сдачи", "Исполнитель", "Исполнитель кредитует заказчика своим временем и материалами"],
        ["Частичный аванс 30-50 %", "Обе стороны", "Риск делится, но остается у каждой стороны"],
        ["Счет эскроу в ИЖС (186-ФЗ) [7; 8]", "Риск снижен", "Только строительство жилых домов, выплата после завершения всего объекта, а не по этапам"],
        ["Безопасная сделка на площадках [15]", "Площадка", "Действует внутри одной площадки, деньги хранит посредник, правила задает площадка"],
        ["Отчеты и проверки по грантам [11]", "Грантодатель", "Нарушение выявляется после расходования средств"],
        ["Венчурные инвестиции и инвестиционные платформы [19; 21]", "Инвестор", "Деньги передаются проекту целиком, инвестор выбирает зрелые проекты, ранние стадии остаются без финансирования"],
    ], [4.2, 3.0, 9.3])

    D.h1("7", "Направление решения")
    D.p("Из причин следуют требования к механизму оплаты: деньги заказчика резервируются до начала работы и остаются вне распоряжения обеих сторон; работа делится на этапы с суммами и критериями приемки, которые стороны подтверждают заранее; исполнитель видит, что оплата этапа обеспечена, и получает ее сразу после приемки; при отказе или истечении сроков остаток автоматически возвращается заказчику; спор решает независимый приемщик. Для проектов тот же механизм позволяет грантодателю, спонсорам и инвесторам выдавать деньги по этапам после подтверждения результата: риск потери средств ограничен суммой текущего этапа, поэтому финансировать новые проекты становится менее рискованно.")
    D.p("Инфраструктура для такого механизма появляется на государственном уровне. С 1 сентября 2026 года крупнейшие банки обязаны предоставлять клиентам операции с цифровым рублем [16]. Банк России опубликовал концепцию платформы коммерческих смарт-контрактов в цифровых рублях, где условия расчета исполняются автоматически [17]. Минфин России и Банк России испытывают программируемые платежи для контроля целевого использования средств [18].")
    D.p("Проект StepPay реализует эти требования: вся сумма сделки размещается на счете эскроу в банке-партнере и высвобождается по мере приемки этапов, а проценты на остаток получает заказчик. Заказчик не теряет аванс, исполнитель не работает без гарантии оплаты, автор проекта получает финансирование по этапам, а тот, кто финансирует, видит расходование средств.")

    D.pagebreak()
    unnumbered("ЗАКЛЮЧЕНИЕ")
    D.p("Проблема предоплаты проявляется трижды. Аванс не гарантирует результат: в ИЖС около 5 тыс. льготных заемщиков не получили дом от подрядчика, а число пострадавших от недобросовестных подрядчиков оценивается более чем в 20 тыс. человек; нарушения при субсидиях юридическим лицам составили 354,7 млрд руб. Выполненная работа не гарантирует оплату: неплатежи контрагентов назвали главным ограничением 42 % компаний в четвертом квартале 2025 года, просроченная дебиторская задолженность достигла 8,2 трлн руб. Проекты не получают финансирования: грант Фонда президентских грантов получают около 15 % заявителей, число венчурных сделок в 2025 году сократилось на 42 %, финансирование посевной стадии на 67 %.")
